%% |valid citations come in first-appearance order with their metadata| example |a repeated marker is cited once, where it first appears| — laws/citations.lawspec:192
law_valid_citations_come_in_first_appearance_order__a_repeated_marker_is_cited_once_where_it_first() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_4(
        [
            make_marker([2], Schema),
            make_cons_4(
                [
                    make_plain([<<" and ">>], Schema),
                    make_cons_4(
                        [
                            make_marker([1], Schema),
                            make_cons_4(
                                [
                                    make_plain([<<" again ">>], Schema),
                                    make_cons_4([make_marker([2], Schema), []], Schema)
                                ],
                                Schema
                            )
                        ],
                        Schema
                    )
                ],
                Schema
            )
        ],
        Schema
    ),
    Slots = make_cons_2(
        [
            make_slot(
                [
                    1,
                    make_citable_meta(
                        [
                            <<"chunk-1">>,
                            <<"Programming Elixir — Page 1"/utf8>>,
                            <<"One">>,
                            make_absent([], Schema)
                        ],
                        Schema
                    )
                ],
                Schema
            ),
            make_cons_2(
                [
                    make_slot(
                        [
                            2,
                            make_citable_meta(
                                [
                                    <<"chunk-2">>,
                                    <<"Programming Elixir — Page 2"/utf8>>,
                                    <<"Two">>,
                                    make_present([<<"books/programming-elixir.pdf">>], Schema)
                                ],
                                Schema
                            )
                        ],
                        Schema
                    ),
                    []
                ],
                Schema
            )
        ],
        Schema
    ),
    lawspec_beam_runtime:require(
        law_valid_citations_come_in_first_appearance_order(Schema, Symbols, [Segments, Slots]),
        ?LAW_VALID_CITATIONS_COME_IN_FIRST_APPEARANCE_ORDER
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:cake_laws_shared_render(Schema, Symbols, Segments),
        <<"[2] and [1] again [2]">>,
        <<"|valid citations come in first-appearance order with their metadata| example |a repeated marker is cited once, where it first appears| — laws/citations.lawspec:192"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:indices_of(
            Schema,
            Symbols,
            lawspec_beam_schema:match(
                lawspec_definitions:extract(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_shared_render(Schema, Symbols, Segments),
                    lawspec_definitions:chunk_map_of(Schema, Symbols, Slots)
                ),
                #{
                    <<"cake.laws.citations::type::Extraction::Extraction">> => fun(
                        [Valid, _Hallucinated]
                    ) ->
                        Valid
                    end
                }
            )
        ),
        [2, 1],
        <<"|valid citations come in first-appearance order with their metadata| example |a repeated marker is cited once, where it first appears| — laws/citations.lawspec:193"/utf8>>
    ).

